# Static Assets for Mnemosyne Landing Page & Fallbacks
HTML_CONTENT = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n  <title>Mnemosyne — Codebase Memory Graph</title>\n\n  <!-- Google Fonts: Inter -->\n  <link rel="preconnect" href="https://fonts.googleapis.com" />\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />\n  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet" />\n\n  <!-- BubbledotICG-FinePos font via OnlineWebFonts CDN -->\n  <link\n    href="https://db.onlinewebfonts.com/c/8cb707a9b8a73f8a7403336b861c3074?family=BubbledotICG-FinePos"\n    rel="stylesheet"\n  />\n\n  <!-- Font Awesome 6.5.2 -->\n  <link\n    rel="stylesheet"\n    href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"\n    integrity="sha512-SnH5WK+bZxgPHs44uWIX+LLJAJ9/2PkPKZ5QiAj6Ta86w+fsb2TkcmfRyVX3pBnMFcV7oQPJkl9QevSCWr3W6A=="\n    crossorigin="anonymous"\n    referrerpolicy="no-referrer"\n  />\n\n  <!-- D3.js v7 for Graph Visualizer -->\n  <script src="https://d3js.org/d3.v7.min.js"></script>\n\n  <link rel="stylesheet" href="styles.css" />\n</head>\n<body>\n  <!-- Full-viewport cover video -->\n  <div class="bg">\n    <video class="bg-video" autoplay muted loop playsinline>\n      <source\n        src="https://d8j0ntlcm91z4.cloudfront.net/user_38xzZboKViGWJOttwIXH07lWA1P/hf_20260809_012548_ef22562c-c0ae-4816-ad9d-f8922af4e6a7.mp4"\n        type="video/mp4"\n      />\n    </video>\n  </div>\n\n  <div class="page">\n    <!-- 1) Header -->\n    <header class="header">\n      <button class="logo-btn" aria-label="Return to Home" data-tab="home">\n        <img src="assets/logo.webp" alt="Mnemosyne Logo" width="52" height="52" />\n      </button>\n\n      <nav class="nav-pill" aria-label="Main Navigation">\n        <button class="nav-link active" data-tab="home">Home</button>\n        <button class="nav-link" data-tab="dashboard">Dashboard</button>\n        <button class="nav-link" data-tab="remember">Remember Bug</button>\n        <button class="nav-link" data-tab="recall">Recall Search</button>\n        <button class="nav-link" data-tab="rules">Rules</button>\n        <button class="nav-link" data-tab="security">Security</button>\n        <button class="nav-link" data-tab="visualizer">Visualizer</button>\n      </nav>\n\n      <button class="sign-in-btn" id="header-status-btn" title="View System Status" data-tab="dashboard">\n        <span class="status-pulse-dot" id="system-pulse-dot"></span>\n        <span id="system-status-text">Cognee Active</span>\n      </button>\n\n      <button class="burger-btn" aria-label="Toggle navigation" aria-expanded="false" id="burger-btn">\n        <span class="burger-bar"></span>\n        <span class="burger-bar"></span>\n        <span class="burger-bar"></span>\n      </button>\n    </header>\n\n    <!-- Mobile Menu Overlay & Sheet -->\n    <div class="mobile-overlay" id="mobile-overlay" hidden></div>\n    <div class="mobile-sheet" id="mobile-sheet" hidden aria-label="Mobile Navigation">\n      <button class="mobile-link active" data-tab="home">Home</button>\n      <button class="mobile-link" data-tab="dashboard">📊 Dashboard</button>\n      <button class="mobile-link" data-tab="remember">💾 Remember Bug</button>\n      <button class="mobile-link" data-tab="recall">🔍 Recall Search</button>\n      <button class="mobile-link" data-tab="rules">📜 Consolidated Rules</button>\n      <button class="mobile-link" data-tab="security">🛡️ Security Scan</button>\n      <button class="mobile-link" data-tab="visualizer">🕸️ Graph Visualizer</button>\n      <div class="mobile-status-row">\n        <span class="status-pulse-dot" id="mobile-pulse-dot"></span>\n        <span id="mobile-status-text">Cognee Cloud Active</span>\n      </div>\n    </div>\n\n    <!-- =========================================================\n         Main Viewport: All Sections seamlessly styled like Pic 2\n         ========================================================= -->\n    <main class="main-viewport">\n      <!-- -------------------------------------------------------\n           VIEW 0: Home Hero (Main Overview)\n           ------------------------------------------------------- -->\n      <section class="page-view active hero" id="view-home">\n        <!-- Project Stack Pill -->\n        <div class="trust-row anim" style="--d: 0.05s">\n          <div class="tech-stack-badges">\n            <div class="tech-badge" title="Cognee AI Memory Engine">\n              <div class="inner-circle"><i class="fa-solid fa-brain"></i></div>\n            </div>\n            <div class="tech-badge" title="Git Commit & History Ingestion">\n              <div class="inner-circle"><i class="fa-brands fa-git-alt"></i></div>\n            </div>\n            <div class="tech-badge" title="Python 3.10+ Native Engine">\n              <div class="inner-circle"><i class="fa-brands fa-python"></i></div>\n            </div>\n          </div>\n          <div class="trust-pill" id="hero-status-pill">\n            <span class="status-pulse-dot" id="hero-pulse-dot"></span>\n            <span id="hero-status-text">Codebase Memory Graph</span>\n          </div>\n        </div>\n\n        <!-- Headline in dot-matrix font -->\n        <h1 class="headline anim">\n          <span class="headline-line headline-line-1">Mnemosyne</span>\n          <span class="headline-line headline-line-2">Codebase Memory Graph</span>\n        </h1>\n\n        <!-- Subhead -->\n        <p class="subhead anim" style="--d: 0.28s">\n          Persistent memory for engineering teams. Ingests git commits, recalls bug fixes,<br />synthesizes team rules with Cognee AI, and guards against code regressions.\n        </p>\n\n        <!-- CTA -->\n        <button class="cta-btn" id="hero-get-started-btn" style="--d: 0.4s" data-tab="dashboard">\n          <span>Explore Memory Graph</span>\n        </button>\n      </section>\n\n      <!-- -------------------------------------------------------\n           VIEW 1: Dashboard (Live Telemetry & Graph Health)\n           ------------------------------------------------------- -->\n      <section class="page-view" id="view-dashboard">\n        <div class="view-header-block">\n          <h2 class="view-title">Memory Statistics & Graph Health</h2>\n          <p class="view-subtitle">Real-time graph telemetry, active memory nodes, and AI reasoning engine state</p>\n        </div>\n\n        <div class="dashboard-grid-container">\n          <div class="dashboard-stats-grid">\n            <div class="glass-stat-card">\n              <span class="card-icon">🕸️</span>\n              <div class="card-body">\n                <span class="card-number" id="dash-total-nodes">0</span>\n                <span class="card-label">Total Graph Nodes</span>\n              </div>\n            </div>\n            <div class="glass-stat-card">\n              <span class="card-icon">🪲</span>\n              <div class="card-body">\n                <span class="card-number" id="dash-bug-fixes">0</span>\n                <span class="card-label">Bug Fix Memories</span>\n              </div>\n            </div>\n            <div class="glass-stat-card">\n              <span class="card-icon">📜</span>\n              <div class="card-body">\n                <span class="card-number" id="dash-rules">0</span>\n                <span class="card-label">Consolidated Rules</span>\n              </div>\n            </div>\n            <div class="glass-stat-card">\n              <span class="card-icon">💾</span>\n              <div class="card-body">\n                <span class="card-number" id="dash-commits">0</span>\n                <span class="card-label">Commit Memories</span>\n              </div>\n            </div>\n          </div>\n\n          <div class="dashboard-details-row">\n            <div class="glass-detail-box">\n              <h4>🤖 AI Engine Reasoning Capabilities</h4>\n              <ul class="capability-list">\n                <li><span class="chk">✓</span> <strong>remember()</strong>: Ingests commit history & manual bugs into structured CodeKnowledgeGraph.</li>\n                <li><span class="chk">✓</span> <strong>recall()</strong>: Traverses relational nodes using hybrid vector + graph search.</li>\n                <li><span class="chk">✓</span> <strong>memify()</strong>: Clusters recurring bug fixes into generalized team rules.</li>\n                <li><span class="chk">✓</span> <strong>forget()</strong>: Prunes stale connections and removes decayed nodes.</li>\n              </ul>\n            </div>\n\n            <div class="glass-detail-box">\n              <h4>🛡️ Core Connection Status</h4>\n              <div class="status-rows">\n                <div class="status-row-item">\n                  <span>Cognee Graph Engine</span>\n                  <span class="badge" id="badge-cognee">Checking...</span>\n                </div>\n                <div class="status-row-item">\n                  <span>LLM Embedding Engine</span>\n                  <span class="badge" id="badge-llm">Checking...</span>\n                </div>\n                <div class="status-row-item">\n                  <span>Local Offline Fallback</span>\n                  <span class="badge" id="badge-fallback">Active</span>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- -------------------------------------------------------\n           VIEW 2: Remember Bug (Ingest Memory)\n           ------------------------------------------------------- -->\n      <section class="page-view" id="view-remember">\n        <div class="view-header-block">\n          <h2 class="view-title">Ingest Bug Fix Memory</h2>\n          <p class="view-subtitle">Teach Mnemosyne about historical bugs and root causes to prevent future regressions</p>\n        </div>\n\n        <form class="glass-form" id="bug-ingest-form">\n          <div class="form-row-2">\n            <div class="form-group">\n              <label for="bug-file-path">File Path <span class="req">*</span></label>\n              <input type="text" id="bug-file-path" placeholder="e.g., utils/image_processor.py" required />\n            </div>\n            <div class="form-group">\n              <label for="bug-title">Bug Summary / Title <span class="req">*</span></label>\n              <input type="text" id="bug-title" placeholder="e.g., Memory leak in thumbnail batch processing" required />\n            </div>\n          </div>\n\n          <div class="form-group">\n            <label for="bug-root-cause">Root Cause Analysis <span class="req">*</span></label>\n            <textarea id="bug-root-cause" rows="2" placeholder="Describe the underlying technical mechanism that triggered the issue..." required></textarea>\n          </div>\n\n          <div class="form-group">\n            <label for="bug-fix-desc">Fix Description & Patterns Applied <span class="req">*</span></label>\n            <textarea id="bug-fix-desc" rows="2" placeholder="Describe the solution applied, architectural fixes, or refactoring..." required></textarea>\n          </div>\n\n          <div class="form-row-2">\n            <div class="form-group">\n              <label for="bug-severity">Severity Level</label>\n              <select id="bug-severity">\n                <option value="low">Low - Minor cosmetic or non-blocking</option>\n                <option value="medium" selected>Medium - Functional defect with workaround</option>\n                <option value="high">High - System disruption or critical feature broken</option>\n                <option value="critical">Critical - Crash, data loss or security vulnerability</option>\n              </select>\n            </div>\n            <div class="form-group">\n              <label for="bug-tags">Tags (Comma-separated)</label>\n              <input type="text" id="bug-tags" placeholder="memory, leak, threading, pil" />\n            </div>\n          </div>\n\n          <div class="form-actions">\n            <button type="submit" class="cta-btn small-btn" id="btn-submit-bug">\n              <span>💾 Ingest into Memory Graph</span>\n            </button>\n            <div class="form-message" id="bug-form-message"></div>\n          </div>\n        </form>\n      </section>\n\n      <!-- -------------------------------------------------------\n           VIEW 3: Recall Search (Hybrid Traversal)\n           ------------------------------------------------------- -->\n      <section class="page-view" id="view-recall">\n        <div class="view-header-block">\n          <h2 class="view-title">Recall Search</h2>\n          <p class="view-subtitle">Query codebase memory using hybrid semantic embeddings + knowledge graph traversal</p>\n        </div>\n\n        <div class="search-panel-wrapper">\n          <div class="search-bar-row">\n            <div class="search-input-wrapper">\n              <i class="fa-solid fa-magnifying-glass search-icon"></i>\n              <input type="text" id="recall-query" placeholder="Search memories, bugs, architectural lessons (e.g. \'memory leak\')..." />\n            </div>\n            <div class="context-input-wrapper">\n              <input type="text" id="recall-context" placeholder="File context filter (optional)" />\n            </div>\n            <button class="cta-btn small-btn" id="btn-run-recall">Search</button>\n          </div>\n\n          <div class="search-results-container" id="recall-results-list">\n            <p class="empty-state-text">Type a query above to traverse the codebase knowledge graph.</p>\n          </div>\n        </div>\n      </section>\n\n      <!-- -------------------------------------------------------\n           VIEW 4: Consolidated Rules (Synthesized Team Knowledge)\n           ------------------------------------------------------- -->\n      <section class="page-view" id="view-rules">\n        <div class="view-header-block flex-header">\n          <div>\n            <h2 class="view-title" style="text-align: left;">Consolidated Architectural Rules</h2>\n            <p class="view-subtitle" style="text-align: left; margin-bottom: 0;">Team rules synthesized by AI reflection clustering across recurring bug patterns</p>\n          </div>\n          <button class="cta-btn small-btn" id="btn-reflect-rules">\n            <span>✨ Reflect & Generalize Rules</span>\n          </button>\n        </div>\n\n        <div class="table-container">\n          <table class="glass-table">\n            <thead>\n              <tr>\n                <th style="width: 26%;">Rule Title</th>\n                <th style="width: 48%;">Synthesized Guidance</th>\n                <th style="width: 13%;">Domain</th>\n                <th style="width: 13%;">Confidence</th>\n              </tr>\n            </thead>\n            <tbody id="rules-table-body">\n              <tr>\n                <td colspan="4" class="empty-state-text">Loading consolidated rules...</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n      </section>\n\n      <!-- -------------------------------------------------------\n           VIEW 5: Security Scan (Diff & Anti-Pattern Audit)\n           ------------------------------------------------------- -->\n      <section class="page-view" id="view-security">\n        <div class="view-header-block">\n          <h2 class="view-title">Security & Anti-Pattern Scanner</h2>\n          <p class="view-subtitle">Scans code diffs or local files against historical bug rules and vulnerability patterns</p>\n        </div>\n\n        <div class="scan-panel-wrapper">\n          <div class="scan-input-section">\n            <div class="scan-mode-row">\n              <label for="security-diff-input">Code Diff to Inspect</label>\n              <button type="button" class="text-action-link" id="btn-prefill-diff">Prefill Sample Vulnerability</button>\n            </div>\n            <textarea id="security-diff-input" rows="4" placeholder="Paste git diff here (+ file = open(...) without context manager)..."></textarea>\n\n            <div class="scan-file-row">\n              <input type="text" id="security-file-input" placeholder="Or enter local file path (e.g. api/index.py)" />\n              <button class="cta-btn small-btn" id="btn-run-scan">Run Security Scan</button>\n            </div>\n          </div>\n\n          <div class="scan-results-container" id="security-results-panel">\n            <h4 class="findings-heading">Vulnerability Findings</h4>\n            <div class="issues-list" id="security-issues-list">\n              <p class="empty-state-text">Paste a diff or specify a file to run the security scanning agent.</p>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- -------------------------------------------------------\n           VIEW 6: Graph Visualizer (D3 Interactive Network)\n           ------------------------------------------------------- -->\n      <section class="page-view" id="view-visualizer">\n        <div class="view-header-block flex-header">\n          <div>\n            <h2 class="view-title" style="text-align: left;">Knowledge Graph Visualizer</h2>\n            <p class="view-subtitle" style="text-align: left; margin-bottom: 0;">Interactive relations between tenants, files, bugs, commits, and rules</p>\n          </div>\n          <div class="graph-legend">\n            <span class="legend-item"><span class="legend-dot tenant"></span>Tenant</span>\n            <span class="legend-item"><span class="legend-dot file"></span>File</span>\n            <span class="legend-item"><span class="legend-dot bug"></span>Bug</span>\n            <span class="legend-item"><span class="legend-dot rule"></span>Rule</span>\n            <span class="legend-item"><span class="legend-dot commit"></span>Commit</span>\n          </div>\n        </div>\n\n        <div class="visualizer-wrapper">\n          <svg id="graph-svg" class="graph-canvas"></svg>\n\n          <!-- Slide-out Node Inspector Drawer -->\n          <div class="node-inspector-drawer hide" id="node-drawer">\n            <div class="drawer-header">\n              <h4 id="drawer-node-title">Node Metadata</h4>\n              <button class="drawer-close-btn" id="drawer-close-btn">✕</button>\n            </div>\n            <div class="drawer-body" id="drawer-node-content">\n              <p class="empty-state-text">Click on any node in the graph to view relational properties.</p>\n            </div>\n          </div>\n        </div>\n      </section>\n    </main>\n\n    <!-- 3) Stats Footer (4 Metrics Synced with Live Graph Telemetry) -->\n    <footer class="stats-footer">\n      <div class="stat-item anim" style="--d: 0.5s">\n        <div class="stat-glyph">&lt;</div>\n        <div class="stat-value" id="stat-total-nodes-val" data-target="40" data-suffix="" data-decimals="0" data-index="0">40</div>\n        <div class="stat-label">Total Graph Nodes</div>\n      </div>\n\n      <div class="stat-item anim" style="--d: 0.58s">\n        <div class="stat-glyph">%</div>\n        <div class="stat-value" id="stat-bug-fixes-val" data-target="7" data-suffix="" data-decimals="0" data-index="1">7</div>\n        <div class="stat-label">Bug Fix Memories</div>\n      </div>\n\n      <div class="stat-item anim" style="--d: 0.66s">\n        <div class="stat-glyph">*</div>\n        <div class="stat-value" id="stat-rules-val" data-target="14" data-suffix="" data-decimals="0" data-index="2">14</div>\n        <div class="stat-label">Consolidated Rules</div>\n      </div>\n\n      <div class="stat-item anim" style="--d: 0.74s">\n        <div class="stat-glyph">#</div>\n        <div class="stat-value" id="stat-commits-val" data-target="5" data-suffix="" data-decimals="0" data-index="3">5</div>\n        <div class="stat-label">Commit Memories</div>\n      </div>\n    </footer>\n  </div>\n\n  <script src="main.js"></script>\n</body>\n</html>\n'

CSS_CONTENT = ':root {\n  --bg: #000000;\n  --text: #ffffff;\n  --muted: #8e8e8e;\n  --nav-text: #2e2e2e;\n  --pill-dark: #28282a;\n  --sign-in-text: #c8c8c8;\n  --nav-shadow: 0 4px 14px rgba(0, 0, 0, 0.16);\n  --trust-bg: #28282a;\n  --trust-border: rgba(255, 255, 255, 0.4);\n  --trust-text: #c4c2c3;\n  --font-sans: "Inter", "Segoe UI", system-ui, sans-serif;\n  --font-display: "BubbledotICG-FinePos", "Geist Pixel Circle", monospace;\n\n  /* Accent & Status Colors */\n  --primary-accent: #ff007f;\n  --primary-glow: rgba(255, 0, 127, 0.35);\n  --success: #10b981;\n  --warning: #f59e0b;\n  --danger: #ef4444;\n  --info: #3b82f6;\n  --card-glass: rgba(14, 14, 18, 0.68);\n  --border-subtle: rgba(255, 255, 255, 0.14);\n}\n\n@font-face {\n  font-family: "Geist Pixel Circle";\n  src: url("fonts/GeistPixel-Circle.woff2") format("woff2");\n  font-weight: 400;\n  font-style: normal;\n  font-display: swap;\n}\n\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nhtml, body {\n  width: 100%;\n  height: 100vh;\n  height: 100dvh;\n  overflow: hidden;\n  background-color: var(--bg);\n  color: var(--text);\n  font-family: var(--font-sans);\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n  text-rendering: optimizeLegibility;\n}\n\n/* Background video */\n.bg {\n  position: absolute;\n  inset: 0;\n  background-color: var(--bg);\n  overflow: hidden;\n  z-index: 0;\n}\n\n.bg-video {\n  position: absolute;\n  inset: 0;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  pointer-events: none;\n  z-index: 0;\n}\n\n/* Page Layout */\n.page {\n  position: relative;\n  z-index: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: space-between;\n  width: 100%;\n  height: 100vh;\n  height: 100dvh;\n  padding: clamp(14px, 2.2vh, 24px) clamp(14px, 3vw, 32px);\n  overflow: hidden;\n}\n\n/* =========================================================\n   1) Header (Desktop & Mobile)\n   ========================================================= */\n.header {\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 100%;\n  max-width: 860px;\n  gap: clamp(12px, 2vw, 24px);\n  flex-shrink: 0;\n  animation: slideDown 0.7s cubic-bezier(0.22, 1, 0.36, 1) both;\n  z-index: 10;\n}\n\n/* Logo Button */\n.logo-btn {\n  width: clamp(42px, 4.5vw, 48px);\n  height: clamp(42px, 4.5vw, 48px);\n  border-radius: 50%;\n  background-color: #000000;\n  border: 1.5px solid rgba(255, 255, 255, 0.25);\n  box-shadow: 0 0 16px rgba(168, 85, 247, 0.4);\n  display: grid;\n  place-items: center;\n  padding: 0;\n  cursor: pointer;\n  text-decoration: none;\n  flex-shrink: 0;\n  overflow: hidden;\n  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;\n}\n\n.logo-btn:hover {\n  transform: scale(1.08);\n  border-color: rgba(255, 255, 255, 0.5);\n  box-shadow: 0 0 24px rgba(168, 85, 247, 0.7);\n}\n\n.logo-btn img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  display: block;\n  border-radius: 50%;\n}\n\n/* Nav Pill (White) */\n.nav-pill {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  background-color: #ffffff;\n  height: clamp(44px, 5.2vw, 48px);\n  max-width: 600px;\n  flex: 1;\n  padding: 4px 6px;\n  border-radius: 999px;\n  box-shadow: var(--nav-shadow);\n  gap: 2px;\n}\n\n.nav-link {\n  flex: 1;\n  text-align: center;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  height: 100%;\n  font-family: var(--font-sans);\n  font-weight: 500;\n  font-size: clamp(12px, 1.25vw, 14px);\n  letter-spacing: -0.01em;\n  color: var(--nav-text);\n  text-decoration: none;\n  position: relative;\n  opacity: 0.55;\n  transition: opacity 0.2s ease;\n  padding: 0 clamp(4px, 0.8vw, 8px);\n  background: none;\n  border: none;\n  cursor: pointer;\n  white-space: nowrap;\n}\n\n.nav-link:hover {\n  opacity: 0.85;\n}\n\n.nav-link.active {\n  opacity: 1;\n  font-weight: 600;\n}\n\n.nav-link.active::after {\n  content: "";\n  position: absolute;\n  bottom: 5px;\n  left: 50%;\n  transform: translateX(-50%);\n  width: 3px;\n  height: 3px;\n  background-color: #000000;\n  border-radius: 50%;\n  box-shadow: -5px 0 0 #000000, 5px 0 0 #000000;\n}\n\n/* Status / Sign In Pill */\n.sign-in-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  background-color: var(--pill-dark);\n  color: var(--sign-in-text);\n  height: clamp(44px, 5.2vw, 48px);\n  padding: 0 clamp(14px, 1.8vw, 20px);\n  border-radius: 999px;\n  box-shadow: var(--nav-shadow);\n  font-family: var(--font-sans);\n  font-weight: 500;\n  font-size: clamp(12.5px, 1.3vw, 14px);\n  letter-spacing: -0.01em;\n  text-decoration: none;\n  border: none;\n  cursor: pointer;\n  white-space: nowrap;\n  flex-shrink: 0;\n  gap: 8px;\n  transition: background-color 0.2s ease, color 0.2s ease, transform 0.2s ease;\n}\n\n.sign-in-btn:hover {\n  background-color: #323234;\n  color: #ffffff;\n  transform: translateY(-1px);\n}\n\n.status-pulse-dot {\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background-color: var(--success);\n  box-shadow: 0 0 8px var(--success);\n  display: inline-block;\n  animation: pulseGreen 2s infinite ease-in-out;\n}\n\n.status-pulse-dot.offline {\n  background-color: var(--warning);\n  box-shadow: 0 0 8px var(--warning);\n}\n\n@keyframes pulseGreen {\n  0%, 100% {\n    transform: scale(1);\n    opacity: 0.9;\n  }\n  50% {\n    transform: scale(1.3);\n    opacity: 0.5;\n  }\n}\n\n/* Mobile Burger */\n.burger-btn {\n  display: none;\n  width: 48px;\n  height: 48px;\n  border-radius: 50%;\n  background-color: var(--pill-dark);\n  border: none;\n  cursor: pointer;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 5px;\n  padding: 0;\n  box-shadow: var(--nav-shadow);\n  transition: background-color 0.25s ease, transform 0.25s ease;\n  z-index: 101;\n}\n\n.burger-bar {\n  width: 18px;\n  height: 1.5px;\n  background-color: #ffffff;\n  border-radius: 1px;\n  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1), opacity 0.2s ease, background-color 0.25s ease;\n}\n\n.burger-btn[aria-expanded="true"] {\n  background-color: #ffffff;\n}\n\n.burger-btn[aria-expanded="true"] .burger-bar {\n  background-color: #000000;\n}\n\n.burger-btn[aria-expanded="true"] .burger-bar:nth-child(1) {\n  transform: translateY(6.5px) rotate(45deg);\n}\n\n.burger-btn[aria-expanded="true"] .burger-bar:nth-child(2) {\n  opacity: 0;\n  transform: scaleX(0);\n}\n\n.burger-btn[aria-expanded="true"] .burger-bar:nth-child(3) {\n  transform: translateY(-6.5px) rotate(-45deg);\n}\n\n/* Mobile Overlay & Sheet */\n.mobile-overlay {\n  display: none;\n  position: fixed;\n  inset: 0;\n  background-color: rgba(0, 0, 0, 0.62);\n  backdrop-filter: blur(6px);\n  -webkit-backdrop-filter: blur(6px);\n  z-index: 99;\n  animation: overlayIn 0.28s ease forwards;\n}\n\n.mobile-overlay:not([hidden]) {\n  display: block;\n}\n\n.mobile-sheet {\n  display: none;\n  position: fixed;\n  top: 76px;\n  left: 50%;\n  transform: translateX(-50%);\n  width: min(360px, calc(100% - 32px));\n  background-color: #ffffff;\n  border-radius: 28px;\n  padding: 22px 18px 20px;\n  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.45);\n  z-index: 100;\n  animation: menuIn 0.38s cubic-bezier(0.22, 1, 0.36, 1) forwards;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.mobile-sheet:not([hidden]) {\n  display: flex;\n}\n\n.mobile-link {\n  display: flex;\n  align-items: center;\n  justify-content: flex-start;\n  padding: 10px 16px;\n  font-family: var(--font-sans);\n  font-weight: 500;\n  font-size: 15px;\n  letter-spacing: -0.01em;\n  color: var(--nav-text);\n  text-decoration: none;\n  position: relative;\n  background: none;\n  border: none;\n  border-radius: 12px;\n  cursor: pointer;\n  opacity: 0;\n  animation: linkIn 0.35s cubic-bezier(0.22, 1, 0.36, 1) forwards;\n  transition: background 0.2s ease;\n}\n\n.mobile-link:hover {\n  background: rgba(0, 0, 0, 0.05);\n}\n\n.mobile-sheet:not([hidden]) .mobile-link:nth-child(1) { animation-delay: 0.03s; }\n.mobile-sheet:not([hidden]) .mobile-link:nth-child(2) { animation-delay: 0.06s; }\n.mobile-sheet:not([hidden]) .mobile-link:nth-child(3) { animation-delay: 0.09s; }\n.mobile-sheet:not([hidden]) .mobile-link:nth-child(4) { animation-delay: 0.12s; }\n.mobile-sheet:not([hidden]) .mobile-link:nth-child(5) { animation-delay: 0.15s; }\n.mobile-sheet:not([hidden]) .mobile-link:nth-child(6) { animation-delay: 0.18s; }\n.mobile-sheet:not([hidden]) .mobile-link:nth-child(7) { animation-delay: 0.21s; }\n.mobile-sheet:not([hidden]) .mobile-status-row { animation-delay: 0.24s; }\n\n.mobile-link.active {\n  font-weight: 600;\n  background: rgba(0, 0, 0, 0.06);\n}\n\n.mobile-link.active::after {\n  content: "";\n  position: absolute;\n  right: 16px;\n  top: 50%;\n  transform: translateY(-50%);\n  width: 4px;\n  height: 4px;\n  background-color: #000000;\n  border-radius: 50%;\n  box-shadow: -6px 0 0 #000000, 6px 0 0 #000000;\n}\n\n.mobile-status-row {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  width: 100%;\n  height: 42px;\n  background-color: #f4f4f5;\n  color: #3f3f46;\n  border-radius: 999px;\n  font-family: var(--font-sans);\n  font-weight: 500;\n  font-size: 13.5px;\n  margin-top: 8px;\n  gap: 8px;\n  opacity: 0;\n  animation: linkIn 0.35s cubic-bezier(0.22, 1, 0.36, 1) forwards;\n}\n\n/* =========================================================\n   2) Main Viewport & Shared Section Styling (Matching Pic 2)\n   ========================================================= */\n.main-viewport {\n  flex: 1;\n  min-height: 0;\n  width: 100%;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  position: relative;\n  padding: 6px 0;\n  overflow: hidden;\n}\n\n.page-view {\n  width: 100%;\n  max-width: 1040px;\n  height: 100%;\n  display: none;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n}\n\n.page-view.active {\n  display: flex;\n  animation: viewFadeIn 0.35s cubic-bezier(0.22, 1, 0.36, 1) forwards;\n}\n\n@keyframes viewFadeIn {\n  from {\n    opacity: 0;\n    transform: translateY(14px) scale(0.99);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0) scale(1);\n  }\n}\n\n/* Standardized View Headers in Dot-Matrix Font */\n.view-header-block {\n  margin-bottom: 14px;\n  text-align: center;\n  width: 100%;\n  flex-shrink: 0;\n}\n\n.view-title {\n  font-family: var(--font-display);\n  font-size: clamp(20px, 2.8vw, 32px);\n  color: #000000;\n  letter-spacing: -0.03em;\n  line-height: 1.15;\n  margin-bottom: 4px;\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.view-subtitle {\n  font-family: var(--font-sans);\n  font-size: clamp(12px, 1.2vw, 13.5px);\n  color: #000000;\n  opacity: 1;\n  font-weight: 500;\n  line-height: 1.45;\n}\n\n.flex-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  flex-wrap: wrap;\n  gap: 12px;\n}\n\n/* Standardized White CTA Button */\n.cta-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  background-color: #ffffff;\n  color: #000000;\n  font-family: var(--font-sans);\n  font-weight: 600;\n  font-size: clamp(13px, 1.4vw, 14.5px);\n  padding: clamp(10px, 1.4vh, 12px) clamp(22px, 2.8vw, 28px);\n  border-radius: 999px;\n  text-decoration: none;\n  border: none;\n  cursor: pointer;\n  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.15),\n              0 0 22px rgba(255, 255, 255, 0.32),\n              0 0 44px rgba(255, 255, 255, 0.12);\n  transition: transform 0.25s ease, box-shadow 0.25s ease;\n  animation: revealPulse 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;\n  animation-delay: var(--d, 0.4s);\n  white-space: nowrap;\n}\n\n.cta-btn.small-btn {\n  font-size: 13px;\n  padding: 8px 20px;\n  animation: none;\n}\n\n.cta-btn:hover {\n  transform: translateY(-2px) scale(1.02);\n  box-shadow: 0 0 0 1px rgba(255, 255, 255, 0.25),\n              0 0 28px rgba(255, 255, 255, 0.45),\n              0 0 54px rgba(255, 255, 255, 0.2);\n}\n\n/* =========================================================\n   Section 0: Home Hero Styles\n   ========================================================= */\n.hero {\n  max-width: 900px;\n}\n\n.trust-row {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  margin-bottom: clamp(14px, 2vh, 22px);\n  --trust-size: clamp(36px, 4.2vw, 42px);\n}\n\n.tech-stack-badges {\n  display: inline-flex;\n  align-items: center;\n  position: relative;\n}\n\n.tech-badge {\n  width: var(--trust-size);\n  height: var(--trust-size);\n  border-radius: 50%;\n  background-color: var(--trust-bg);\n  border: 1px solid var(--trust-border);\n  padding: 5px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-sizing: border-box;\n  position: relative;\n  transition: transform 0.35s ease;\n}\n\n.tech-badge .inner-circle {\n  width: 100%;\n  height: 100%;\n  border-radius: 50%;\n  background-color: rgba(255, 255, 255, 0.08);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.tech-badge i {\n  font-size: calc(var(--trust-size) * 0.44);\n}\n\n.tech-badge:nth-child(1) { z-index: 1; color: #ff007f; }\n.tech-badge:nth-child(2) { z-index: 2; margin-left: calc(var(--trust-size) * -0.42); color: #f97316; }\n.tech-badge:nth-child(3) { z-index: 4; margin-left: calc(var(--trust-size) * -0.42); color: #38bdf8; }\n\n.tech-badge:hover {\n  transform: translateY(-3px);\n}\n\n.trust-pill {\n  display: inline-flex;\n  align-items: center;\n  height: var(--trust-size);\n  background-color: var(--trust-bg);\n  border: 1px solid var(--trust-border);\n  border-radius: 999px;\n  margin-left: calc(var(--trust-size) * -0.42);\n  padding-left: calc(var(--trust-size) * 0.58);\n  padding-right: clamp(14px, 1.8vw, 20px);\n  z-index: 5;\n  color: var(--trust-text);\n  font-family: var(--font-sans);\n  font-weight: 500;\n  font-size: clamp(12px, 1.4vw, 13.5px);\n  white-space: nowrap;\n  gap: 7px;\n}\n\n.headline {\n  margin: 0 0 clamp(12px, 1.8vh, 18px);\n  font-family: var(--font-display);\n  color: #000000;\n  font-size: clamp(28px, 5.8vw, 76px);\n  font-weight: 400;\n  letter-spacing: -0.04em;\n  line-height: 1.12;\n  white-space: nowrap;\n  overflow: hidden;\n  text-align: center;\n}\n\n.headline.anim {\n  opacity: 1 !important;\n  transform: none !important;\n  filter: none !important;\n  animation: none !important;\n}\n\n.headline-line {\n  display: block;\n  opacity: 0;\n  transform: translateY(14px);\n  animation: headlineFade 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;\n  color: #000000;\n}\n\n.headline-line-1 { animation-delay: 0.12s; }\n.headline-line-2 { animation-delay: 0.3s; }\n\n.subhead {\n  max-width: min(520px, 92%);\n  font-family: var(--font-sans);\n  font-size: clamp(calc(13px + 2pt), calc(1.5vw + 2pt), calc(16px + 2pt));\n  color: #d0d0d0;\n  opacity: 0.8;\n  line-height: 1.55;\n  font-weight: 400;\n  margin: 0 auto clamp(18px, 2.6vh, 28px);\n  text-align: center;\n}\n\n/* =========================================================\n   Section 1: Dashboard Styles (Matching Pic 2)\n   ========================================================= */\n.dashboard-grid-container {\n  width: 100%;\n  max-height: calc(100vh - 210px);\n  overflow-y: auto;\n  padding: 4px 6px;\n}\n\n.dashboard-grid-container::-webkit-scrollbar { width: 5px; }\n.dashboard-grid-container::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.2); border-radius: 3px; }\n\n.dashboard-stats-grid {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  gap: 14px;\n  margin-bottom: 16px;\n  width: 100%;\n}\n\n.glass-stat-card {\n  background: var(--card-glass);\n  backdrop-filter: blur(24px);\n  -webkit-backdrop-filter: blur(24px);\n  border: 1px solid var(--border-subtle);\n  border-radius: 18px;\n  padding: 16px 18px;\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.1);\n  transition: transform 0.25s ease, border-color 0.25s ease, box-shadow 0.25s ease;\n}\n\n.glass-stat-card:hover {\n  transform: translateY(-2px);\n  border-color: rgba(255, 255, 255, 0.35);\n  box-shadow: 0 16px 44px rgba(0, 0, 0, 0.6), 0 0 20px rgba(255, 255, 255, 0.08);\n}\n\n.glass-stat-card .card-icon {\n  font-size: 28px;\n}\n\n.glass-stat-card .card-body {\n  display: flex;\n  flex-direction: column;\n  text-align: left;\n}\n\n.glass-stat-card .card-number {\n  font-size: 24px;\n  font-weight: 700;\n  color: #ffffff;\n  font-variant-numeric: tabular-nums;\n  line-height: 1.1;\n}\n\n.glass-stat-card .card-label {\n  font-size: 11.5px;\n  color: var(--muted);\n  margin-top: 3px;\n  white-space: nowrap;\n}\n\n.dashboard-details-row {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 16px;\n  width: 100%;\n}\n\n.glass-detail-box {\n  background: var(--card-glass);\n  backdrop-filter: blur(24px);\n  -webkit-backdrop-filter: blur(24px);\n  border: 1px solid var(--border-subtle);\n  border-radius: 18px;\n  padding: 18px 20px;\n  text-align: left;\n  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.5);\n}\n\n.glass-detail-box h4 {\n  font-size: 14px;\n  font-weight: 600;\n  color: #ffffff;\n  margin-bottom: 12px;\n}\n\n.capability-list {\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  font-size: 12.5px;\n  color: #d4d4d8;\n  line-height: 1.4;\n}\n\n.capability-list .chk {\n  color: var(--success);\n  font-weight: bold;\n  margin-right: 6px;\n}\n\n.status-rows {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.status-row-item {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding-bottom: 8px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.06);\n  font-size: 13px;\n  color: #e4e4e7;\n}\n\n.badge {\n  font-size: 11px;\n  padding: 3px 10px;\n  border-radius: 999px;\n  font-weight: 600;\n}\n\n.badge.active {\n  background: rgba(16, 185, 129, 0.16);\n  color: #34d399;\n  border: 1px solid rgba(16, 185, 129, 0.35);\n}\n\n.badge.offline {\n  background: rgba(245, 158, 11, 0.16);\n  color: #fbbf24;\n  border: 1px solid rgba(245, 158, 11, 0.35);\n}\n\n/* =========================================================\n   Section 2: Remember Bug Form (Matching Pic 2)\n   ========================================================= */\n.glass-form {\n  width: 100%;\n  max-width: 840px;\n  background: var(--card-glass);\n  backdrop-filter: blur(26px);\n  -webkit-backdrop-filter: blur(26px);\n  border: 1px solid var(--border-subtle);\n  border-radius: 20px;\n  padding: 22px 26px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  text-align: left;\n  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.6);\n  max-height: calc(100vh - 220px);\n  overflow-y: auto;\n}\n\n.form-row-2 {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 14px;\n}\n\n.form-group {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.form-group label {\n  font-size: 12px;\n  font-weight: 500;\n  color: #e4e4e7;\n}\n\n.form-group .req {\n  color: var(--primary-accent);\n}\n\n.form-group input,\n.form-group textarea,\n.form-group select {\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.15);\n  border-radius: 12px;\n  padding: 9px 13px;\n  color: #ffffff;\n  font-family: var(--font-sans);\n  font-size: 13px;\n  outline: none;\n  transition: all 0.2s ease;\n}\n\n.form-group input:focus,\n.form-group textarea:focus,\n.form-group select:focus {\n  border-color: rgba(255, 255, 255, 0.45);\n  box-shadow: 0 0 16px rgba(255, 255, 255, 0.15);\n  background: rgba(255, 255, 255, 0.08);\n}\n\n.form-group select option {\n  background: #18181b;\n  color: #ffffff;\n}\n\n.form-actions {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  margin-top: 6px;\n}\n\n.form-message {\n  font-size: 12.5px;\n}\n.form-message.success { color: var(--success); }\n.form-message.error { color: var(--danger); }\n\n/* =========================================================\n   Section 3: Recall Search (Matching Pic 2)\n   ========================================================= */\n.search-panel-wrapper {\n  width: 100%;\n  max-width: 900px;\n  max-height: calc(100vh - 210px);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n.search-bar-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  margin-bottom: 14px;\n  width: 100%;\n  flex-shrink: 0;\n}\n\n.search-input-wrapper {\n  position: relative;\n  flex: 2;\n}\n\n.search-input-wrapper .search-icon {\n  position: absolute;\n  left: 14px;\n  top: 50%;\n  transform: translateY(-50%);\n  color: var(--muted);\n  font-size: 14px;\n}\n\n.search-input-wrapper input {\n  width: 100%;\n  padding-left: 38px;\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.16);\n  border-radius: 999px;\n  padding-top: 10px;\n  padding-bottom: 10px;\n  padding-right: 16px;\n  color: #ffffff;\n  font-family: var(--font-sans);\n  font-size: 13px;\n  outline: none;\n  backdrop-filter: blur(16px);\n}\n\n.search-input-wrapper input:focus {\n  border-color: rgba(255, 255, 255, 0.45);\n  box-shadow: 0 0 18px rgba(255, 255, 255, 0.15);\n}\n\n.context-input-wrapper {\n  flex: 1;\n}\n\n.context-input-wrapper input {\n  width: 100%;\n  background: rgba(255, 255, 255, 0.06);\n  border: 1px solid rgba(255, 255, 255, 0.16);\n  border-radius: 999px;\n  padding: 10px 16px;\n  color: #ffffff;\n  font-family: var(--font-sans);\n  font-size: 13px;\n  outline: none;\n  backdrop-filter: blur(16px);\n}\n\n.search-results-container {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  overflow-y: auto;\n  padding-right: 4px;\n}\n\n.search-results-container::-webkit-scrollbar { width: 5px; }\n.search-results-container::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.2); border-radius: 3px; }\n\n.memory-result-card {\n  background: var(--card-glass);\n  backdrop-filter: blur(20px);\n  -webkit-backdrop-filter: blur(20px);\n  border: 1px solid var(--border-subtle);\n  border-radius: 16px;\n  padding: 14px 18px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  text-align: left;\n  transition: transform 0.2s ease, border-color 0.2s ease;\n}\n\n.memory-result-card:hover {\n  transform: translateY(-1px);\n  border-color: rgba(255, 255, 255, 0.35);\n}\n\n.result-card-top {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.result-card-title {\n  font-size: 14.5px;\n  font-weight: 600;\n  color: #ffffff;\n}\n\n.strategy-badge {\n  font-size: 10px;\n  font-weight: 700;\n  letter-spacing: 0.04em;\n  padding: 3px 8px;\n  border-radius: 999px;\n  background: rgba(255, 0, 127, 0.18);\n  color: #ff66b3;\n  border: 1px solid rgba(255, 0, 127, 0.35);\n}\n\n.result-file-path {\n  font-size: 11.5px;\n  color: #a1a1aa;\n  font-family: monospace;\n}\n\n.result-meta-body {\n  font-size: 12.5px;\n  color: #d4d4d8;\n  line-height: 1.45;\n}\n\n.empty-state-text {\n  color: var(--muted);\n  font-size: 13px;\n  text-align: center;\n  padding: 24px 10px;\n}\n\n/* =========================================================\n   Section 4: Consolidated Rules (Matching Pic 2)\n   ========================================================= */\n.table-container {\n  width: 100%;\n  max-width: 960px;\n  max-height: calc(100vh - 220px);\n  overflow-y: auto;\n  border: 1px solid var(--border-subtle);\n  border-radius: 18px;\n  background: var(--card-glass);\n  backdrop-filter: blur(26px);\n  -webkit-backdrop-filter: blur(26px);\n  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.6);\n}\n\n.table-container::-webkit-scrollbar { width: 5px; }\n.table-container::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.2); border-radius: 3px; }\n\n.glass-table {\n  width: 100%;\n  border-collapse: collapse;\n  text-align: left;\n  font-size: 12.5px;\n}\n\n.glass-table th {\n  background: rgba(255, 255, 255, 0.05);\n  padding: 12px 16px;\n  color: #a1a1aa;\n  font-weight: 600;\n  border-bottom: 1px solid var(--border-subtle);\n  font-size: 11px;\n  text-transform: uppercase;\n  letter-spacing: 0.06em;\n  position: sticky;\n  top: 0;\n  backdrop-filter: blur(10px);\n}\n\n.glass-table td {\n  padding: 12px 16px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.05);\n  color: #e4e4e7;\n  line-height: 1.4;\n}\n\n.glass-table tr:hover td {\n  background: rgba(255, 255, 255, 0.03);\n}\n\n.rule-title-cell {\n  font-weight: 600;\n  color: #ffffff;\n}\n\n/* =========================================================\n   Section 5: Security Scanner (Matching Pic 2)\n   ========================================================= */\n.scan-panel-wrapper {\n  width: 100%;\n  max-width: 880px;\n  max-height: calc(100vh - 210px);\n  overflow-y: auto;\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n.scan-input-section {\n  background: var(--card-glass);\n  backdrop-filter: blur(26px);\n  -webkit-backdrop-filter: blur(26px);\n  border: 1px solid var(--border-subtle);\n  border-radius: 18px;\n  padding: 18px 22px;\n  display: flex;\n  flex-direction: column;\n  gap: 12px;\n  text-align: left;\n  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.6);\n}\n\n.scan-mode-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.scan-mode-row label {\n  font-size: 12.5px;\n  font-weight: 500;\n  color: #e4e4e7;\n}\n\n.text-action-link {\n  background: none;\n  border: none;\n  color: #60a5fa;\n  font-size: 12px;\n  cursor: pointer;\n  text-decoration: underline;\n}\n\n.text-action-link:hover { color: #93c5fd; }\n\n.scan-input-section textarea {\n  width: 100%;\n  background: rgba(0, 0, 0, 0.4);\n  border: 1px solid rgba(255, 255, 255, 0.15);\n  border-radius: 12px;\n  padding: 10px 14px;\n  color: #ffffff;\n  font-family: monospace;\n  font-size: 12px;\n  outline: none;\n  resize: vertical;\n}\n\n.scan-file-row {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.scan-file-row input {\n  flex: 1;\n  background: rgba(255, 255, 255, 0.05);\n  border: 1px solid rgba(255, 255, 255, 0.15);\n  border-radius: 999px;\n  padding: 9px 16px;\n  color: #ffffff;\n  font-family: var(--font-sans);\n  font-size: 12.5px;\n  outline: none;\n}\n\n.scan-results-container {\n  text-align: left;\n}\n\n.findings-heading {\n  font-size: 13px;\n  font-weight: 600;\n  color: #ffffff;\n  margin-bottom: 8px;\n}\n\n.issues-list {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.issue-card {\n  background: var(--card-glass);\n  backdrop-filter: blur(20px);\n  border-left: 4px solid #71717a;\n  border-radius: 0 14px 14px 0;\n  padding: 12px 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n\n.issue-card.critical { border-left-color: #ef4444; }\n.issue-card.high { border-left-color: #f97316; }\n.issue-card.medium { border-left-color: #f59e0b; }\n.issue-card.low { border-left-color: #3b82f6; }\n\n.issue-top {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.issue-title {\n  font-size: 13.5px;\n  font-weight: 600;\n  color: #ffffff;\n}\n\n.issue-severity {\n  font-size: 10px;\n  font-weight: 700;\n  padding: 2px 6px;\n  border-radius: 4px;\n  text-transform: uppercase;\n}\n.issue-severity.critical { background: rgba(239, 68, 68, 0.2); color: #f87171; }\n.issue-severity.high { background: rgba(249, 115, 22, 0.2); color: #fb923c; }\n.issue-severity.medium { background: rgba(245, 158, 11, 0.2); color: #fbbf24; }\n.issue-severity.low { background: rgba(59, 130, 246, 0.2); color: #60a5fa; }\n\n.issue-meta {\n  font-size: 12px;\n  color: #d4d4d8;\n}\n\n.issue-fix {\n  font-size: 12px;\n  color: #34d399;\n  background: rgba(16, 185, 129, 0.1);\n  padding: 6px 10px;\n  border-radius: 8px;\n  margin-top: 2px;\n}\n\n/* =========================================================\n   Section 6: Graph Visualizer (Matching Pic 2)\n   ========================================================= */\n.graph-legend {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  font-size: 12px;\n  color: #000000;\n  font-weight: 500;\n}\n\n.legend-item {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  color: #000000;\n  font-weight: 500;\n}\n\n.legend-dot {\n  width: 8px;\n  height: 8px;\n  border-radius: 50%;\n}\n.legend-dot.tenant { background: #ff007f; box-shadow: 0 0 8px #ff007f; }\n.legend-dot.file { background: #06b6d4; }\n.legend-dot.bug { background: #f59e0b; }\n.legend-dot.rule { background: #10b981; }\n.legend-dot.commit { background: #8b5cf6; }\n\n.visualizer-wrapper {\n  position: relative;\n  width: 100%;\n  max-width: 980px;\n  height: calc(100vh - 240px);\n  background: rgba(0, 0, 0, 0.55);\n  backdrop-filter: blur(20px);\n  -webkit-backdrop-filter: blur(20px);\n  border: 1px solid var(--border-subtle);\n  border-radius: 20px;\n  overflow: hidden;\n  box-shadow: 0 16px 48px rgba(0, 0, 0, 0.6);\n}\n\n.graph-canvas {\n  width: 100%;\n  height: 100%;\n}\n\n.node-circle.tenant { fill: #ff007f; filter: drop-shadow(0 0 10px rgba(255, 0, 127, 0.85)); }\n.node-circle.file { fill: #06b6d4; }\n.node-circle.bug { fill: #f59e0b; }\n.node-circle.rule { fill: #10b981; }\n.node-circle.commit { fill: #8b5cf6; }\n\n.node-inspector-drawer {\n  position: absolute;\n  top: 12px;\n  right: 12px;\n  bottom: 12px;\n  width: min(300px, calc(100% - 24px));\n  background: rgba(18, 18, 22, 0.95);\n  border: 1px solid rgba(255, 255, 255, 0.16);\n  backdrop-filter: blur(20px);\n  border-radius: 16px;\n  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.6);\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n  transition: transform 0.3s ease, opacity 0.3s ease;\n  z-index: 10;\n  text-align: left;\n}\n\n.node-inspector-drawer.hide {\n  transform: translateX(110%);\n  opacity: 0;\n  pointer-events: none;\n}\n\n.drawer-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 12px 14px;\n  border-bottom: 1px solid var(--border-subtle);\n}\n\n.drawer-header h4 {\n  font-size: 13px;\n  font-weight: 600;\n  color: #ffffff;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.drawer-close-btn {\n  background: none;\n  border: none;\n  color: var(--muted);\n  cursor: pointer;\n  font-size: 14px;\n}\n.drawer-close-btn:hover { color: #ffffff; }\n\n.drawer-body {\n  padding: 12px 14px;\n  overflow-y: auto;\n  font-size: 12px;\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.detail-row {\n  display: flex;\n  flex-direction: column;\n  gap: 2px;\n  padding-bottom: 6px;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.05);\n}\n\n.detail-label {\n  font-size: 10px;\n  text-transform: uppercase;\n  color: var(--muted);\n  letter-spacing: 0.04em;\n}\n\n.detail-value {\n  color: #ffffff;\n  word-break: break-word;\n}\n\n/* =========================================================\n   3) Stats Footer (4 Metrics Synced to Live Telemetry)\n   ========================================================= */\n.stats-footer {\n  display: grid;\n  grid-template-columns: repeat(4, 1fr);\n  width: 100%;\n  max-width: 920px;\n  gap: clamp(16px, 3vw, 40px);\n  margin-top: auto;\n  flex-shrink: 0;\n  text-align: center;\n}\n\n.stat-item {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n}\n\n.stat-glyph {\n  font-family: var(--font-display);\n  font-size: clamp(22px, 3vw, 33px);\n  color: #ffffff;\n  line-height: 1;\n  margin-bottom: 6px;\n}\n\n.stat-value {\n  font-family: var(--font-sans);\n  color: #ffffff;\n  font-size: clamp(18px, 2.2vw, 26px);\n  font-weight: 600;\n  letter-spacing: -0.025em;\n  font-variant-numeric: tabular-nums;\n  line-height: 1.15;\n  margin-bottom: 4px;\n}\n\n.stat-label {\n  color: var(--muted);\n  font-family: var(--font-sans);\n  font-size: clamp(11px, 1.2vw, 12.5px);\n  white-space: nowrap;\n}\n\n/* Shared Entrance Animations */\n.anim {\n  opacity: 0;\n  transform: translateY(22px) scale(0.98);\n  filter: blur(6px);\n  animation: reveal 0.85s cubic-bezier(0.22, 1, 0.36, 1) forwards;\n  animation-delay: var(--d, 0s);\n}\n\n@keyframes reveal {\n  to {\n    opacity: 1;\n    transform: translateY(0) scale(1);\n    filter: blur(0);\n  }\n}\n\n@keyframes revealPulse {\n  0% {\n    opacity: 0;\n    transform: translateY(22px) scale(0.96);\n    filter: blur(6px);\n  }\n  70% {\n    opacity: 1;\n    transform: translateY(-2px) scale(1.02);\n    filter: blur(0);\n  }\n  100% {\n    opacity: 1;\n    transform: translateY(0) scale(1);\n    filter: blur(0);\n  }\n}\n\n@keyframes slideDown {\n  from { opacity: 0; transform: translateY(-18px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n@keyframes headlineFade {\n  from { opacity: 0; transform: translateY(14px); }\n  to { opacity: 1; transform: translateY(0); }\n}\n\n@keyframes overlayIn {\n  from { opacity: 0; }\n  to { opacity: 1; }\n}\n\n@keyframes menuIn {\n  from {\n    opacity: 0;\n    transform: translate(-50%, -12px) scale(0.96);\n  }\n  to {\n    opacity: 1;\n    transform: translate(-50%, 0) scale(1);\n  }\n}\n\n@keyframes linkIn {\n  from {\n    opacity: 0;\n    transform: translateY(10px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n/* =========================================================\n   Responsive Breakpoints\n   ========================================================= */\n@media (max-width: 820px) {\n  .dashboard-stats-grid {\n    grid-template-columns: repeat(2, 1fr);\n  }\n  .dashboard-details-row {\n    grid-template-columns: 1fr;\n  }\n  .form-row-2 {\n    grid-template-columns: 1fr;\n  }\n}\n\n@media (max-width: 720px) {\n  .header {\n    justify-content: space-between;\n    max-width: 100%;\n  }\n\n  .logo-btn {\n    width: 48px;\n    height: 48px;\n  }\n\n  .nav-pill,\n  .sign-in-btn {\n    display: none;\n  }\n\n  .burger-btn {\n    display: flex;\n  }\n\n  .headline {\n    letter-spacing: -0.08em;\n    line-height: 1.05;\n  }\n\n  .stats-footer {\n    grid-template-columns: repeat(2, 1fr);\n    gap: 16px 20px;\n  }\n\n  .search-bar-row {\n    flex-direction: column;\n    align-items: stretch;\n  }\n\n  .scan-file-row {\n    flex-direction: column;\n    align-items: stretch;\n  }\n}\n\n@media (max-width: 420px) {\n  .trust-row {\n    --trust-size: 34px;\n  }\n\n  .trust-pill {\n    font-size: 12px;\n  }\n\n  .headline {\n    letter-spacing: -0.09em;\n    line-height: 1.04;\n  }\n}\n\n@media (max-height: 700px) {\n  .page {\n    padding-top: 10px;\n    padding-bottom: 10px;\n  }\n\n  .trust-row { margin-bottom: 10px; }\n  .headline { margin-bottom: 8px; }\n  .subhead { margin-bottom: 14px; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  *, *::before, *::after {\n    animation-duration: 0.01ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: 0.01ms !important;\n    scroll-behavior: auto !important;\n  }\n  .anim,\n  .headline-line,\n  .cta-btn,\n  .header,\n  .page-view {\n    opacity: 1 !important;\n    transform: none !important;\n    filter: none !important;\n    animation: none !important;\n  }\n  .headline {\n    color: #000000 !important;\n  }\n}\n'

JS_CONTENT = 'document.addEventListener("DOMContentLoaded", () => {\n  const API_BASE = window.location.origin.startsWith("file") ? "http://127.0.0.1:8085" : window.location.origin;\n\n  // =========================================================\n  // API Call Helper\n  // =========================================================\n  async function apiCall(endpoint, method = "GET", body = null) {\n    const options = {\n      method,\n      headers: { "Content-Type": "application/json" }\n    };\n    if (body) {\n      options.body = JSON.stringify(body);\n    }\n    try {\n      const res = await fetch(`${API_BASE}${endpoint}`, options);\n      if (!res.ok) {\n        const err = await res.json().catch(() => ({}));\n        throw new Error(err.detail || `Request failed with status ${res.status}`);\n      }\n      return await res.json();\n    } catch (e) {\n      console.error(`API Error (${endpoint}):`, e);\n      throw e;\n    }\n  }\n\n  // =========================================================\n  // Viewport Section Navigation (Seamless UI matching Pic 2)\n  // =========================================================\n  const navLinks = document.querySelectorAll(".nav-link");\n  const mobileLinks = document.querySelectorAll(".mobile-link");\n  const pageViews = document.querySelectorAll(".page-view");\n  const logoBtn = document.querySelector(".logo-btn");\n  const heroGetStartedBtn = document.getElementById("hero-get-started-btn");\n  const headerStatusBtn = document.getElementById("header-status-btn");\n\n  let currentTab = "home";\n\n  function switchTab(tabName) {\n    if (!tabName) tabName = "home";\n    currentTab = tabName;\n\n    // 1. Sync Header Nav Links\n    navLinks.forEach((link) => {\n      if (link.getAttribute("data-tab") === tabName) {\n        link.classList.add("active");\n      } else {\n        link.classList.remove("active");\n      }\n    });\n\n    // 2. Sync Mobile Menu Links\n    mobileLinks.forEach((link) => {\n      if (link.getAttribute("data-tab") === tabName) {\n        link.classList.add("active");\n      } else {\n        link.classList.remove("active");\n      }\n    });\n\n    // 3. Show Corresponding Viewport Section\n    pageViews.forEach((view) => {\n      if (view.id === `view-${tabName}`) {\n        view.classList.add("active");\n      } else {\n        view.classList.remove("active");\n      }\n    });\n\n    // Close mobile sheet if open\n    closeMobileMenu();\n\n    // 4. Trigger Section Loaders\n    if (tabName === "dashboard") refreshDashboard();\n    if (tabName === "rules") refreshRules();\n    if (tabName === "visualizer") {\n      // Delay slightly for container size to settle\n      setTimeout(initD3Graph, 50);\n    }\n  }\n\n  // Attach click listeners to all tab buttons\n  navLinks.forEach((link) => {\n    link.addEventListener("click", () => {\n      const tab = link.getAttribute("data-tab");\n      switchTab(tab);\n    });\n  });\n\n  if (logoBtn) {\n    logoBtn.addEventListener("click", () => {\n      switchTab("home");\n    });\n  }\n\n  if (heroGetStartedBtn) {\n    heroGetStartedBtn.addEventListener("click", () => {\n      switchTab("dashboard");\n    });\n  }\n\n  if (headerStatusBtn) {\n    headerStatusBtn.addEventListener("click", () => {\n      switchTab("dashboard");\n    });\n  }\n\n  // =========================================================\n  // Mobile Menu Interactions\n  // =========================================================\n  const burgerBtn = document.getElementById("burger-btn");\n  const mobileOverlay = document.getElementById("mobile-overlay");\n  const mobileSheet = document.getElementById("mobile-sheet");\n\n  function openMobileMenu() {\n    if (!burgerBtn) return;\n    burgerBtn.setAttribute("aria-expanded", "true");\n    if (mobileOverlay) mobileOverlay.removeAttribute("hidden");\n    if (mobileSheet) mobileSheet.removeAttribute("hidden");\n  }\n\n  function closeMobileMenu() {\n    if (!burgerBtn) return;\n    burgerBtn.setAttribute("aria-expanded", "false");\n    if (mobileOverlay) mobileOverlay.setAttribute("hidden", "");\n    if (mobileSheet) mobileSheet.setAttribute("hidden", "");\n  }\n\n  function toggleMobileMenu() {\n    const isExpanded = burgerBtn && burgerBtn.getAttribute("aria-expanded") === "true";\n    if (isExpanded) closeMobileMenu();\n    else openMobileMenu();\n  }\n\n  if (burgerBtn && mobileOverlay && mobileSheet) {\n    burgerBtn.addEventListener("click", (e) => {\n      e.stopPropagation();\n      toggleMobileMenu();\n    });\n\n    mobileOverlay.addEventListener("click", closeMobileMenu);\n\n    mobileLinks.forEach((link) => {\n      link.addEventListener("click", () => {\n        const tab = link.getAttribute("data-tab");\n        switchTab(tab);\n      });\n    });\n  }\n\n  // Keyboard Escape Handler\n  document.addEventListener("keydown", (e) => {\n    if (e.key === "Escape") {\n      if (burgerBtn && burgerBtn.getAttribute("aria-expanded") === "true") {\n        closeMobileMenu();\n      } else if (currentTab !== "home") {\n        switchTab("home");\n      }\n    }\n  });\n\n  // Resize Handler\n  window.addEventListener("resize", () => {\n    if (window.innerWidth > 720 && burgerBtn && burgerBtn.getAttribute("aria-expanded") === "true") {\n      closeMobileMenu();\n    }\n  });\n\n  // =========================================================\n  // 1. Dashboard Status & Telemetry\n  // =========================================================\n  const dashTotalNodes = document.getElementById("dash-total-nodes");\n  const dashBugFixes = document.getElementById("dash-bug-fixes");\n  const dashRules = document.getElementById("dash-rules");\n  const dashCommits = document.getElementById("dash-commits");\n  const badgeCognee = document.getElementById("badge-cognee");\n  const badgeLlm = document.getElementById("badge-llm");\n  const badgeFallback = document.getElementById("badge-fallback");\n\n  const systemPulseDot = document.getElementById("system-pulse-dot");\n  const systemStatusText = document.getElementById("system-status-text");\n  const mobilePulseDot = document.getElementById("mobile-pulse-dot");\n  const mobileStatusText = document.getElementById("mobile-status-text");\n\n  function setBadge(el, active) {\n    if (!el) return;\n    el.textContent = active ? "Active" : "Offline";\n    el.className = `badge ${active ? "active" : "offline"}`;\n  }\n\n  async function refreshDashboard() {\n    try {\n      const data = await apiCall("/api/status");\n\n      const totalNodes = (data.total_memories || 0) + (data.rule_nodes || 0);\n      const bugFixes = data.bug_fixes || 0;\n      const rules = data.rule_nodes || 0;\n      const commits = data.commit_memories || 0;\n\n      // Update Dashboard view counters\n      if (dashTotalNodes) dashTotalNodes.textContent = totalNodes;\n      if (dashBugFixes) dashBugFixes.textContent = bugFixes;\n      if (dashRules) dashRules.textContent = rules;\n      if (dashCommits) dashCommits.textContent = commits;\n\n      // Sync Front Page Footer Stats\n      const statTotalNodesEl = document.getElementById("stat-total-nodes-val");\n      const statBugFixesEl = document.getElementById("stat-bug-fixes-val");\n      const statRulesEl = document.getElementById("stat-rules-val");\n      const statCommitsEl = document.getElementById("stat-commits-val");\n\n      if (statTotalNodesEl) {\n        statTotalNodesEl.setAttribute("data-target", totalNodes);\n        statTotalNodesEl.textContent = totalNodes;\n      }\n      if (statBugFixesEl) {\n        statBugFixesEl.setAttribute("data-target", bugFixes);\n        statBugFixesEl.textContent = bugFixes;\n      }\n      if (statRulesEl) {\n        statRulesEl.setAttribute("data-target", rules);\n        statRulesEl.textContent = rules;\n      }\n      if (statCommitsEl) {\n        statCommitsEl.setAttribute("data-target", commits);\n        statCommitsEl.textContent = commits;\n      }\n\n      // Update Badges\n      setBadge(badgeCognee, data.cognee_active);\n      setBadge(badgeLlm, data.llm_active);\n      setBadge(badgeFallback, data.offline_mode);\n\n      // Status labels\n      const statusLabel = data.cognee_active ? "Cognee Active" : "Fallback Active";\n      if (systemStatusText) systemStatusText.textContent = statusLabel;\n      if (mobileStatusText) mobileStatusText.textContent = statusLabel;\n\n      const heroPulseDot = document.getElementById("hero-pulse-dot");\n      const heroStatusText = document.getElementById("hero-status-text");\n      if (heroStatusText) {\n        heroStatusText.textContent = data.cognee_active ? "Code Knowledge Graph Active" : "Codebase Memory Graph (Local Fallback)";\n      }\n      if (heroPulseDot) {\n        heroPulseDot.className = `status-pulse-dot ${data.cognee_active ? "" : "offline"}`;\n      }\n\n      if (systemPulseDot) systemPulseDot.className = `status-pulse-dot ${data.cognee_active ? "" : "offline"}`;\n      if (mobilePulseDot) mobilePulseDot.className = `status-pulse-dot ${data.cognee_active ? "" : "offline"}`;\n    } catch (e) {\n      if (systemStatusText) systemStatusText.textContent = "Fallback Active";\n      if (mobileStatusText) mobileStatusText.textContent = "Fallback Active";\n      if (systemPulseDot) systemPulseDot.className = "status-pulse-dot offline";\n      if (mobilePulseDot) mobilePulseDot.className = "status-pulse-dot offline";\n      setBadge(badgeCognee, false);\n      setBadge(badgeLlm, false);\n      setBadge(badgeFallback, true);\n    }\n  }\n\n  // Pre-load telemetry on startup\n  refreshDashboard();\n\n  // =========================================================\n  // 2. Remember Bug Form Ingestion\n  // =========================================================\n  const bugForm = document.getElementById("bug-ingest-form");\n  const bugMsg = document.getElementById("bug-form-message");\n  const btnSubmitBug = document.getElementById("btn-submit-bug");\n\n  if (bugForm) {\n    bugForm.addEventListener("submit", async (e) => {\n      e.preventDefault();\n      bugMsg.textContent = "";\n      bugMsg.className = "form-message";\n      btnSubmitBug.disabled = true;\n\n      const tagsRaw = document.getElementById("bug-tags").value;\n      const tags = tagsRaw ? tagsRaw.split(",").map((t) => t.trim()).filter(Boolean) : [];\n\n      const payload = {\n        file_path: document.getElementById("bug-file-path").value.trim(),\n        title: document.getElementById("bug-title").value.trim(),\n        root_cause: document.getElementById("bug-root-cause").value.trim(),\n        fix_description: document.getElementById("bug-fix-desc").value.trim(),\n        severity: document.getElementById("bug-severity").value,\n        tags: tags\n      };\n\n      try {\n        const res = await apiCall("/api/remember-bug", "POST", payload);\n        bugMsg.textContent = `✓ Bug successfully logged into Graph Memory! (Node ID: ${res.id})`;\n        bugMsg.className = "form-message success";\n        bugForm.reset();\n        refreshDashboard();\n      } catch (err) {\n        bugMsg.textContent = `Error: ${err.message}`;\n        bugMsg.className = "form-message error";\n      } finally {\n        btnSubmitBug.disabled = false;\n      }\n    });\n  }\n\n  // =========================================================\n  // 3. Recall Search\n  // =========================================================\n  const recallQuery = document.getElementById("recall-query");\n  const recallContext = document.getElementById("recall-context");\n  const btnRunRecall = document.getElementById("btn-run-recall");\n  const recallResultsList = document.getElementById("recall-results-list");\n\n  async function performRecall() {\n    const query = recallQuery.value.trim();\n    const file_context = recallContext.value.trim() || null;\n    if (!query) return;\n\n    btnRunRecall.disabled = true;\n    recallResultsList.innerHTML = \'<p class="empty-state-text">Traversing knowledge graph and vector indices...</p>\';\n\n    try {\n      const data = await apiCall("/api/recall", "POST", { query, file_context, top_k: 6 });\n      recallResultsList.innerHTML = "";\n\n      if (!data.results || data.results.length === 0) {\n        recallResultsList.innerHTML = \'<p class="empty-state-text">No matching memories found for this query.</p>\';\n        return;\n      }\n\n      data.results.forEach((rec) => {\n        const card = document.createElement("div");\n        card.className = "memory-result-card";\n        const meta = rec.metadata || {};\n        const strategy = rec.search_strategy || "GRAPH_VECTOR_HYBRID";\n\n        card.innerHTML = `\n          <div class="result-card-top">\n            <span class="result-card-title">${rec.title || "Untitled Memory"}</span>\n            <span class="strategy-badge">${strategy}</span>\n          </div>\n          <div class="result-file-path"><i class="fa-regular fa-file-code"></i> ${rec.file_path || "N/A"}</div>\n          <div class="result-meta-body">\n            ${meta.root_cause ? `<p><strong>Root Cause:</strong> ${meta.root_cause}</p>` : ""}\n            ${meta.fix_description ? `<p style="margin-top: 4px;"><strong>Fix Applied:</strong> ${meta.fix_description}</p>` : ""}\n            ${!meta.root_cause && rec.content ? `<p>${rec.content}</p>` : ""}\n          </div>\n        `;\n        recallResultsList.appendChild(card);\n      });\n    } catch (err) {\n      recallResultsList.innerHTML = `<div class="form-message error" style="padding: 16px;">Recall search failed: ${err.message}</div>`;\n    } finally {\n      btnRunRecall.disabled = false;\n    }\n  }\n\n  if (btnRunRecall) btnRunRecall.addEventListener("click", performRecall);\n  if (recallQuery) {\n    recallQuery.addEventListener("keydown", (e) => {\n      if (e.key === "Enter") performRecall();\n    });\n  }\n\n  // =========================================================\n  // 4. Consolidated Rules\n  // =========================================================\n  const rulesTableBody = document.getElementById("rules-table-body");\n  const btnReflectRules = document.getElementById("btn-reflect-rules");\n\n  async function refreshRules() {\n    try {\n      rulesTableBody.innerHTML = \'<tr><td colspan="4" class="empty-state-text">Fetching consolidated rules...</td></tr>\';\n      const data = await apiCall("/api/rules");\n      rulesTableBody.innerHTML = "";\n\n      if (!data.rules || data.rules.length === 0) {\n        rulesTableBody.innerHTML = `\n          <tr>\n            <td colspan="4" class="empty-state-text">No rules consolidated yet. Click "Reflect & Generalize Rules" to cluster bug fixes into rules.</td>\n          </tr>\n        `;\n        return;\n      }\n\n      data.rules.forEach((rule) => {\n        const tr = document.createElement("tr");\n        const meta = rule.metadata || {};\n        const title = meta.rule_title || rule.rule_title || rule.title || "Consolidated Pattern";\n        const desc = meta.description || rule.description || rule.content || "No Description";\n        const domain = meta.domain || rule.domain || "general";\n        const conf = meta.confidence !== undefined ? meta.confidence : 0.95;\n\n        tr.innerHTML = `\n          <td class="rule-title-cell">${title}</td>\n          <td>${desc}</td>\n          <td><span class="badge active" style="font-size: 10px;">${domain.toUpperCase()}</span></td>\n          <td><strong>${(conf * 100).toFixed(0)}%</strong></td>\n        `;\n        rulesTableBody.appendChild(tr);\n      });\n    } catch (e) {\n      rulesTableBody.innerHTML = `<tr><td colspan="4" class="empty-state-text" style="color: var(--danger)">Failed to load coding rules: ${e.message}</td></tr>`;\n    }\n  }\n\n  if (btnReflectRules) {\n    btnReflectRules.addEventListener("click", async () => {\n      btnReflectRules.disabled = true;\n      btnReflectRules.innerHTML = \'<span>⏳ Reflecting & Synthesizing...</span>\';\n      try {\n        await apiCall("/api/reflect", "POST");\n        await refreshRules();\n        await refreshDashboard();\n      } catch (err) {\n        alert(`Rule reflection failed: ${err.message}`);\n      } finally {\n        btnReflectRules.disabled = false;\n        btnReflectRules.innerHTML = \'<span>✨ Reflect & Generalize Rules</span>\';\n      }\n    });\n  }\n\n  // =========================================================\n  // 5. Security Scanner\n  // =========================================================\n  const securityDiffInput = document.getElementById("security-diff-input");\n  const securityFileInput = document.getElementById("security-file-input");\n  const btnRunScan = document.getElementById("btn-run-scan");\n  const btnPrefillDiff = document.getElementById("btn-prefill-diff");\n  const securityIssuesList = document.getElementById("security-issues-list");\n\n  if (btnPrefillDiff) {\n    btnPrefillDiff.addEventListener("click", () => {\n      securityDiffInput.value = `diff --git a/image_pipeline.py b/image_pipeline.py\n--- a/image_pipeline.py\n+++ b/image_pipeline.py\n@@ -10,4 +10,6 @@ def process_file(path):\n+    f = open(path, "r")\n+    data = f.read()\n+    # Missing with-statement and explicit close leads to descriptor leak`;\n    });\n  }\n\n  if (btnRunScan) {\n    btnRunScan.addEventListener("click", async () => {\n      const diffText = securityDiffInput.value.trim();\n      const filePath = securityFileInput.value.trim();\n\n      if (!diffText && !filePath) {\n        alert("Please paste a git diff or provide a file path to scan.");\n        return;\n      }\n\n      btnRunScan.disabled = true;\n      btnRunScan.textContent = "Scanning Codebase Rules...";\n      securityIssuesList.innerHTML = \'<p class="empty-state-text">Auditing against consolidated team anti-patterns...</p>\';\n\n      const payload = diffText ? { diff_text: diffText } : { file_path: filePath };\n\n      try {\n        const data = await apiCall("/api/scan-security", "POST", payload);\n        securityIssuesList.innerHTML = "";\n\n        if (!data.issues || data.issues.length === 0) {\n          securityIssuesList.innerHTML = \'<p class="empty-state-text" style="color: var(--success);">✓ Clean code! No anti-patterns or security violations detected.</p>\';\n          return;\n        }\n\n        data.issues.forEach((issue) => {\n          const card = document.createElement("div");\n          const sev = (issue.severity || "medium").toLowerCase();\n          card.className = `issue-card ${sev}`;\n\n          card.innerHTML = `\n            <div class="issue-top">\n              <span class="issue-title">● ${issue.vulnerability_type || "Security Issue"}</span>\n              <span class="issue-severity ${sev}">${sev.toUpperCase()}</span>\n            </div>\n            <div class="issue-meta">\n              File: <strong>${issue.file_path || "Diff Block"}</strong> ${issue.line_number ? `(Line ${issue.line_number})` : ""}<br />\n              ${issue.description || ""}\n            </div>\n            <div class="issue-fix">\n              <strong>Proposed Fix:</strong> ${issue.proposed_fix || "Apply context manager pattern."}\n            </div>\n          `;\n          securityIssuesList.appendChild(card);\n        });\n      } catch (err) {\n        securityIssuesList.innerHTML = `<div class="form-message error" style="padding: 14px;">Scan error: ${err.message}</div>`;\n      } finally {\n        btnRunScan.disabled = false;\n        btnRunScan.textContent = "Run Security Scan";\n      }\n    });\n  }\n\n  // =========================================================\n  // 6. Interactive D3 Knowledge Graph Visualizer\n  // =========================================================\n  let simulation = null;\n  const nodeDrawer = document.getElementById("node-drawer");\n  const drawerNodeTitle = document.getElementById("drawer-node-title");\n  const drawerNodeContent = document.getElementById("drawer-node-content");\n  const drawerCloseBtn = document.getElementById("drawer-close-btn");\n\n  if (drawerCloseBtn) {\n    drawerCloseBtn.addEventListener("click", () => {\n      nodeDrawer.classList.add("hide");\n    });\n  }\n\n  async function initD3Graph() {\n    if (typeof d3 === "undefined") return;\n\n    const svg = d3.select("#graph-svg");\n    svg.selectAll("*").remove();\n\n    const rect = svg.node().getBoundingClientRect();\n    const width = rect.width || 800;\n    const height = rect.height || 500;\n\n    try {\n      const data = await apiCall("/api/graph-data");\n\n      if (!data.nodes || data.nodes.length === 0) {\n        svg.append("text")\n          .attr("x", width / 2)\n          .attr("y", height / 2)\n          .attr("text-anchor", "middle")\n          .attr("fill", "var(--muted)")\n          .text("Knowledge Graph is currently empty. Ingest some bug fixes to populate!");\n        return;\n      }\n\n      // Marker for arrows\n      svg.append("defs").append("marker")\n        .attr("id", "arrow-marker")\n        .attr("viewBox", "0 -5 10 10")\n        .attr("refX", 22)\n        .attr("refY", 0)\n        .attr("markerWidth", 6)\n        .attr("markerHeight", 6)\n        .attr("orient", "auto")\n        .append("path")\n        .attr("fill", "rgba(255, 0, 127, 0.45)")\n        .attr("d", "M0,-5L10,0L0,5");\n\n      const g = svg.append("g");\n\n      // Zoom & Pan\n      svg.call(\n        d3.zoom()\n          .scaleExtent([0.3, 3])\n          .on("zoom", (event) => {\n            g.attr("transform", event.transform);\n          })\n      );\n\n      // Force Simulation\n      simulation = d3.forceSimulation(data.nodes)\n        .force("link", d3.forceLink(data.links).id((d) => d.id).distance(110))\n        .force("charge", d3.forceManyBody().strength(-240))\n        .force("center", d3.forceCenter(width / 2, height / 2))\n        .force("collision", d3.forceCollide().radius(26));\n\n      // Links\n      const link = g.append("g")\n        .selectAll("line")\n        .data(data.links)\n        .join("line")\n        .attr("stroke", "rgba(255, 255, 255, 0.15)")\n        .attr("stroke-width", 1.5)\n        .attr("marker-end", "url(#arrow-marker)");\n\n      // Nodes\n      const node = g.append("g")\n        .selectAll("g")\n        .data(data.nodes)\n        .join("g")\n        .attr("cursor", "pointer")\n        .call(\n          d3.drag()\n            .on("start", (event, d) => {\n              if (!event.active) simulation.alphaTarget(0.3).restart();\n              d.fx = d.x;\n              d.fy = d.y;\n            })\n            .on("drag", (event, d) => {\n              d.fx = event.x;\n              d.fy = event.y;\n            })\n            .on("end", (event, d) => {\n              if (!event.active) simulation.alphaTarget(0);\n              d.fx = null;\n              d.fy = null;\n            })\n        );\n\n      node.append("circle")\n        .attr("r", (d) => (d.type === "tenant" ? 15 : d.type === "file" ? 11 : 9))\n        .attr("class", (d) => `node-circle ${d.type}`);\n\n      node.append("text")\n        .attr("dy", 22)\n        .attr("text-anchor", "middle")\n        .attr("fill", "#a1a1aa")\n        .attr("font-size", "10px")\n        .text((d) => {\n          const l = d.label || d.id;\n          return l.length > 15 ? l.substring(0, 15) + "…" : l;\n        });\n\n      // Node Click Drawer\n      node.on("click", (event, d) => {\n        event.stopPropagation();\n        nodeDrawer.classList.remove("hide");\n        drawerNodeTitle.textContent = d.label || d.id;\n        drawerNodeContent.innerHTML = "";\n\n        const details = d.details || {};\n        const rows = [\n          { label: "Node Type", val: d.type },\n          { label: "Node ID", val: d.id },\n          ...Object.entries(details).map(([k, v]) => ({ label: k, val: v }))\n        ];\n\n        rows.forEach((r) => {\n          const rowEl = document.createElement("div");\n          rowEl.className = "detail-row";\n          rowEl.innerHTML = `\n            <div class="detail-label">${r.label}</div>\n            <div class="detail-value">${r.val}</div>\n          `;\n          drawerNodeContent.appendChild(rowEl);\n        });\n      });\n\n      svg.on("click", () => nodeDrawer.classList.add("hide"));\n\n      simulation.on("tick", () => {\n        link\n          .attr("x1", (d) => d.source.x)\n          .attr("y1", (d) => d.source.y)\n          .attr("x2", (d) => d.target.x)\n          .attr("y2", (d) => d.target.y);\n\n        node.attr("transform", (d) => `translate(${d.x},${d.y})`);\n      });\n    } catch (e) {\n      console.error("D3 graph rendering error:", e);\n    }\n  }\n\n  // =========================================================\n  // 7. Landing Page Stats Count-Up Animation\n  // =========================================================\n  const statElements = document.querySelectorAll(".stat-value");\n  const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;\n\n  function easeOutCubic(t) {\n    return 1 - Math.pow(1 - t, 3);\n  }\n\n  function animateStat(el, index) {\n    const target = parseFloat(el.getAttribute("data-target"));\n    const suffix = el.getAttribute("data-suffix") || "";\n    const decimals = parseInt(el.getAttribute("data-decimals"), 10) || 0;\n\n    if (prefersReducedMotion || isNaN(target)) {\n      if (!isNaN(target)) el.textContent = target.toFixed(decimals) + suffix;\n      return;\n    }\n\n    const duration = 1400 + index * 80;\n    const delay = 400 + index * 80;\n\n    setTimeout(() => {\n      let startTime = null;\n\n      function step(currentTime) {\n        if (!startTime) startTime = currentTime;\n        const elapsed = currentTime - startTime;\n        const progress = Math.min(elapsed / duration, 1);\n        const currentEased = easeOutCubic(progress);\n        const currentVal = target * currentEased;\n\n        el.textContent = currentVal.toFixed(decimals) + suffix;\n\n        if (progress < 1) {\n          requestAnimationFrame(step);\n        } else {\n          el.textContent = target.toFixed(decimals) + suffix;\n        }\n      }\n\n      requestAnimationFrame(step);\n    }, delay);\n  }\n\n  let statsAnimated = false;\n  const statsFooter = document.querySelector(".stats-footer");\n\n  if (statsFooter && "IntersectionObserver" in window) {\n    const observer = new IntersectionObserver(\n      (entries) => {\n        entries.forEach((entry) => {\n          if (entry.isIntersecting && !statsAnimated) {\n            statsAnimated = true;\n            statElements.forEach((el, i) => animateStat(el, i));\n            observer.unobserve(statsFooter);\n          }\n        });\n      },\n      { threshold: 0.25 }\n    );\n\n    observer.observe(statsFooter);\n  } else {\n    statElements.forEach((el, i) => animateStat(el, i));\n  }\n});\n'
